head.b:skin:
html, body { margin:0; padding:0; min-height:100%; }
body { background:#f8fafc; color:#0f172a; }
.theme-root { font-family:Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
.blogger-content { width:100%; }
.hidden { display:none !important; }

body.script:
// 
window.SYKA_CONFIG = {
  APP_NAME: 'Sykabelajar.id',
  APP_VERSION: '4.3.0-control-plane',

  ROUTE_MODE: 'query',
  APP_PAGE: '/p/app.html',

  ASSET_BASE_URL: 'https://cdn.jsdelivr.net/gh/taufx98/sykabelajar-frontend@main/dist',
  // Phase 13 keeps the legacy UI as default. Set true only when rolling out V2 routing.
  ENABLE_V2: false,

  SUPABASE_URL: 'https://jrfogwueytiddnanetth.supabase.co',
  SUPABASE_PUBLISHABLE_KEY: 'sb_publishable_H3zjdAEE-ItQ08YRj8MieQ_kNMcsAHa',

  CLOUDINARY_CLOUD_NAME: 'sykabelajar',
  CLOUDINARY_UPLOAD_PRESET: 'sykabelajar_preset',
  CLOUDINARY_FOLDER: 'sykabelajar/users/profiles'
};
//

// 
(function () {
  if (window.__SYKA_BOOT_STARTED__) return;
  window.__SYKA_BOOT_STARTED__ = true;

  var BASE = 'https://cdn.jsdelivr.net/gh/taufx98/sykabelajar-frontend@main/dist';
  var MANIFEST = 'https://raw.githubusercontent.com/taufx98/sykabelajar-frontend/refs/heads/main/dist/manifest.json';
  var CACHE_BUST = String(Date.now());

  function addCss(url) {
    return new Promise(function(resolve, reject) {
      var link = document.createElement('link');
      link.rel = 'stylesheet';
      link.href = url;
      link.onload = resolve;
      link.onerror = reject;
      document.head.appendChild(link);
    });
  }

  function addScript(url) {
    return new Promise(function(resolve, reject) {
      var script = document.createElement('script');
      script.src = url;
      script.async = false;
      script.onload = resolve;
      script.onerror = reject;
      document.head.appendChild(script);
    });
  }

  function startApp() {
    if (window.SYKA_APP && typeof window.SYKA_APP.init === 'function') {
      try {
        window.SYKA_APP.init();
      } catch (error) {
        console.error('[Sykabelajar] App init failed:', error);
      }
    } else {
      console.error('[Sykabelajar] App bundle loaded but SYKA_APP.init() is missing.');
    }
  }

  async function activateV2(manifest, assetBase) {
    if (!window.SYKA_CONFIG || window.SYKA_CONFIG.ENABLE_V2 !== true) return;
    if (!manifest.v2 || !manifest.v2.entry) return;
    var v2 = await import(assetBase + '/' + manifest.v2.entry + '?cb=' + CACHE_BUST);
    window.SYKA_V2 = v2;
    if (typeof v2.startSykabelajarV2 === 'function') {
      await v2.startSykabelajarV2({ mode: 'incremental' });
    }
  }

  async function boot() {
    window.SYKA_CONFIG = window.SYKA_CONFIG || {};
    window.SYKA_CONFIG.ASSET_BASE_URL = BASE;

    try {
      var response = await fetch(MANIFEST + '?cb=' + CACHE_BUST, {
        method: 'GET',
        cache: 'no-store',
        credentials: 'omit'
      });

      if (!response.ok) {
        throw new Error('Manifest HTTP ' + response.status);
      }

      var manifest = await response.json();

      if (!manifest || !manifest.styles || !manifest.app || !manifest.vendor) {
        throw new Error('Manifest tidak lengkap.');
      }

      var assetBase = manifest.base || BASE;

      window.__SYKA_RELEASE__ = manifest;
      window.SYKA_CONFIG.ASSET_BASE_URL = assetBase;
      window.SYKA_CONFIG.ASSET_RELEASE = manifest.commit || '';
      window.SYKA_CONFIG.APP_VERSION = manifest.version || manifest.commit || '4.3-runtime';

      await addCss(
        assetBase + '/' + manifest.styles + '?cb=' + CACHE_BUST
      );

      await addScript(
        assetBase + '/' + manifest.vendor + '?cb=' + CACHE_BUST
      );

      await addScript(
        assetBase + '/' + manifest.app + '?cb=' + CACHE_BUST
      );

      startApp();
      await activateV2(manifest, assetBase);
    } catch (error) {
      console.error('[Sykabelajar] Release manifest boot failed:', error);

      // Compatibility fallback for the current repository layout.
      try {
        await addCss(BASE + '/styles.min.css?cb=' + CACHE_BUST);
        await addScript(BASE + '/vendor.min.js?cb=' + CACHE_BUST);
        await addScript(BASE + '/app.min.js?cb=' + CACHE_BUST);
        startApp();
      } catch (fallbackError) {
        console.error('[Sykabelajar] Fallback frontend boot failed:', fallbackError);

        var root = document.getElementById('page-root');
        if (root) {
          root.innerHTML = '<div style="max-width:720px;margin:48px auto;padding:24px;font-family:Inter,system-ui,sans-serif"><h2 style="margin:0 0 8px">Sykabelajar sedang memuat ulang</h2><p style="margin:0 0 16px;color:#64748b">Asset frontend belum tersedia dari CDN. Tunggu beberapa detik lalu refresh halaman.</p><button type="button" onclick="location.reload()" style="padding:10px 16px;border:0;border-radius:10px;background:#7c3aed;color:#fff;font-weight:700;cursor:pointer">Refresh</button></div>';
        }
      }
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot, { once: true });
  } else {
    boot();
  }
})();
//
